# mitm plugin template

yakit_output(MITM_PARAMS)




#--------------------------WORKSPACE-----------------------------


isBypass = cli.Bool("isBypass", cli.setVerboseName("Bypass WAF"),cli.setDefault(false),cli.setCliGroup("config"))
prefix = cli.Text("prefix", cli.setVerboseName("字典前缀"),cli.setCliGroup("config"))
domains = cli.Text("domains", cli.setVerboseName("白名单域名"),cli.setCliGroup("config"))

cli.check()

#白名单检测状态
status = false
if domains != ""{
    domains = str.ParseStringToLines(domains)
    status = true
}


#扫描过的路径
scanPath := make([]string)
#绕过waf的路径
bypassWafPath = ["/.;","/test/..;","/"]
#actuator节点字典
actuatorDocsDict = `
/actuator/env
/actuator/configprops
/actuator/metrics
/actuator/mappings
/actuator/loggers
/actuator/httptrace
/actuator/conditions
/actuator/features
/env
/configprops
/metrics
/mappings
/loggers
/httptrace
/conditions
/features
/act/env
/act/configprops
/act/metrics
/act/mappings
/act/loggers
/act/httptrace
/act/conditions
/act/features
`
actuatorDocsDict = str.ParseStringToLines(actuatorDocsDict)

#actuator 字典
actuatorRootDict = `
/actuator/
/act/
`
actuatorRootDict = str.ParseStringToLines(actuatorRootDict)

#后续扫描的actuator节点字典
scanActuatorDocsDict = make([]string)
#后续扫描的actuator字典
scanActuatorRootDict = make([]string)


#给字典添加前缀
if prefix != ""{
    prefixList = str.ParseStringToLines(prefix)
    for _, i = range prefixList{
        if !str.StartsWith(i, "/"){
            i = "/"+i
        }
        actuatorDocsDict = append(actuatorDocsDict, actuatorDocsDict.Map(fn(tmp){return i+tmp})...)
        actuatorRootDict = append(actuatorRootDict, actuatorRootDict.Map(fn(tmp){return i+tmp})...)
    }
}

scanActuatorDocsDict = append(scanActuatorDocsDict, actuatorDocsDict...)
scanActuatorRootDict = append(scanActuatorRootDict, actuatorRootDict...)

if isBypass{
    for _,i = range bypassWafPath{
        for _, j = range actuatorDocsDict{
            scanActuatorDocsDict.Push(i+j)
        }
        for _,j = range actuatorRootDict{
            scanActuatorRootDict.Push(i+j)
        }
    }
}

parseUrl = func(url){
    return str.ExtractHostPort(url)
}

fingerActuatorApi = [`java`,`spring`,`"levels"`,"bootstrap","jvm."]
fingerActuatorRoot = [`"_links"`,`"templated"`]

# mirrorNewWebsite 每新出现一个网站，这个网站的第一个请求，将会在这里被调用！
mirrorNewWebsite = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    if status {
        if !str.StringContainsAnyOfSubString(parseUrl(url), domains){
            return
        }
    }
    p = parseUrl(url) + "/"
    if p in scanPath{
        return
    }else{
        scanPath.Push(p)
        fuzzReq, err = fuzz.UrlToHTTPRequest("GET",url)
        if err != nil{
            yakit_output("生成fuzz失败")
            return
        }
        apiResults = fuzzReq.FuzzPath(scanActuatorDocsDict...).Exec(fuzz.WithTimeOut(5),httpool.https(isHttps))~
        for result = range apiResults{
            yakit.SaveHTTPFlow(result.Url, result.Request,result.Response )
            if str.StringContainsAnyOfSubString(string(result.ResponseRaw), fingerActuatorApi) && result.Response.StatusCode == 200 && len(result.Response.Header["Content-Type"])>0 &&str.Contains(result.Response.Header["Content-Type"][0], "json"){
                risk.NewRisk(result.Url,
                    risk.description("Actuator 节点泄露"),
                    risk.solution("1、生产环境禁止访问Actuator"),
                    risk.title("Actuator 节点泄露"),
                    risk.request(result.RequestRaw),
                    risk.response(result.ResponseRaw),
                    risk.typeVerbose("Actuator 未授权"),
                    risk.level("low")
                )
                break
            }
        }
        ActuatorResults = fuzzReq.FuzzPath(scanActuatorRootDict...).Exec(fuzz.WithTimeOut(5),httpool.https(isHttps))~
        for result = range ActuatorResults{
            yakit.SaveHTTPFlow(result.Url, result.Request,result.Response )
            if str.StringContainsAnyOfSubString(string(result.ResponseRaw), fingerActuatorRoot)&& result.Response.StatusCode == 200 && len(result.Response.Header["Content-Type"])>0 &&str.Contains(result.Response.Header["Content-Type"][0], "json"){
                risk.NewRisk(result.Url,
                    risk.description("Actuator 泄露"),
                    risk.solution("1、生产环境禁止访问Actuator"),
                    risk.title("Actuator 泄露"),
                    risk.request(result.RequestRaw),
                    risk.response(result.ResponseRaw),
                    risk.typeVerbose("Actuator 未授权"),
                    risk.level("low")
                )
            }
        }
    }
    
}

# mirrorNewWebsitePath 每新出现一个网站路径，关于这个网站路径的第一个请求，将会在这里被传入回调
mirrorNewWebsitePath = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    if url.Contains("hdauthapi"){
        yakit.StatusCard("目标路径" /*type: string*/, "hdauthapi")
    }
    
    if status {
        if !str.StringContainsAnyOfSubString(parseUrl(url), domains){
            return
        }
    }
    pathall = ""
    hostPath = str.Split(url, "//")[1]
    hostPath = str.Split(hostPath, "?")[0]
    parts := str.Split(hostPath, "/")
    url :=str.Split(url, "?")[0]
     if url in scanPath{
            yakit_output(scanPath)
            return
        }else{
            scanPath.Push(url)
            }
    // yakit_output(parts)
    for i := 0; i < len(parts); i++ {
		pathall += parts[i] + "/"
		path = "/"+str.Join(str.Split(pathall, "/")[1:], "/")
            // yakit_output(pathall)
            Dict1 = scanActuatorDocsDict.Map(fn(i){return path+i})
            yakit.Output(Dict1)
            Dict2 = scanActuatorRootDict.Map(fn(i){return path+i})
            fuzzReq, err = fuzz.UrlToHTTPRequest("GET",url)
            if err != nil{
                yakit_output("生成fuzz失败")
                return
            }
            apiResults = fuzzReq.FuzzPath(Dict1...).Exec(fuzz.WithTimeOut(5),httpool.https(isHttps))~
            for result = range apiResults{
                yakit.SaveHTTPFlow(result.Url, result.Request,result.Response )
                
                if str.StringContainsAnyOfSubString(string(result.ResponseRaw), fingerActuatorApi)&& result.Response.StatusCode == 200 && len(result.Response.Header["Content-Type"])>0 &&str.Contains(result.Response.Header["Content-Type"][0], "json"){
                    risk.NewRisk(result.Url,
                        risk.description("Actuator 节点泄露"),
                        risk.solution("1、生产环境禁止访问Actuator"),
                        risk.title("Actuator 节点泄露"),
                        risk.request(result.RequestRaw),
                        risk.response(result.ResponseRaw),
                        risk.typeVerbose("Actuator 未授权"),
                        risk.level("low")
                    )
                    break
                }
            }
            ActuatorResults = fuzzReq.FuzzPath(Dict2...).Exec(fuzz.WithTimeOut(5),httpool.https(isHttps))~
            for result = range ActuatorResults{
                yakit.SaveHTTPFlow(result.Url, result.Request,result.Response )
                if str.StringContainsAnyOfSubString(string(result.ResponseRaw), fingerActuatorRoot)&& result.Response.StatusCode == 200 && len(result.Response.Header["Content-Type"])>0 &&str.Contains(result.Response.Header["Content-Type"][0], "json"){
                    risk.NewRisk(result.Url,
                        risk.description("Actuator 泄露"),
                        risk.solution("1、生产环境禁止访问Actuator"),
                        risk.title("Actuator 泄露"),
                        risk.request(result.RequestRaw),
                        risk.response(result.ResponseRaw),
                        risk.typeVerbose("Actuator 未授权"),
                        risk.level("low")
                    )
                }
            }
        }
}
